package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.sql.SQLException;
import java.util.*;
/** A native major-incident workbench with current command authority and explicit restoration/review. */
final class MajorIncidents {
 private MajorIncidents() {}
 static Map<String,Object> major(Store.Db db,String id)throws SQLException{
  var row=db.one("SELECT * FROM os_major_incident WHERE incident_id=?",id);return row==null?map("incident_id",id,"revision",0,"status","","commander_id","","proposer_id","","proposal","","decision","","impact","","restoration","","review_cause","","review_lessons","","review_actions","","created",now(),"updated",now()):row;
 }
 static String commander(Store.Db db,Object input,String parent)throws SQLException{
  String name=WorkJobs.text(input,80);var account=db.one("SELECT user_id,role FROM os_user WHERE name=? AND active=1 AND password_reset_required=0 AND role IN ('admin','agent')",name);require(account!=null,"Choose active staff with a usable account");String previousId=db.viewerId,previousRole=db.viewerRole;
  try{db.viewerId=account.get("user_id").toString();db.viewerRole=account.get("role").toString();WorkTasks.record(db,"incident",parent);}finally{db.viewerId=previousId;db.viewerRole=previousRole;}return account.get("user_id").toString();
 }
 static List<Map<String,Object>> updates(Store.Db db,String id)throws SQLException{
  return db.all("SELECT p.update_id,p.message,p.created,COALESCE(u.name,'Unavailable account') AS author FROM os_major_update p LEFT JOIN os_user u ON u.user_id=p.actor_id WHERE p.parent_id=? ORDER BY p.ordinal",id);
 }
 static Map<String,Object> page(Store.Db db,String id,Map<String,String> args)throws SQLException{
  var incident=WorkTasks.record(db,"incident",id);var major=major(db,id);var children=new ArrayList<Map<String,Object>>();
  for(var link:db.all("SELECT child_id FROM os_major_link WHERE major_id=? ORDER BY child_id",id))try{var child=WorkTasks.record(db,"incident",link.get("child_id").toString());children.add(FieldAccess.serialize(db,child));}catch(Failure hidden){ /* Relationships never grant access. */ }
  var relation=db.one("SELECT major_id FROM os_major_link WHERE child_id=?",id);Map<String,Object> parent=null;
  if(relation!=null)try{String root=relation.get("major_id").toString();var parentRecord=WorkTasks.record(db,"incident",root);var details=major(db,root);parent=map("incident",FieldAccess.serialize(db,parentRecord),"status",details.get("status"),"impact",details.get("impact"),"restoration",details.get("restoration"),"updates",updates(db,root));}catch(Failure hidden){ /* Keep parent details private after scope changes. */ }
  Map<String,Object> search;try{search=ReferenceSearch.search(db,"incident",args);}catch(Failure denied){if(denied.status!=403)throw denied;search=map("items",List.of(),"total",0,"limit",20,"offset",0,"next_offset",null);}
  for(var candidate:objects(search.get("items"))){String child=candidate.get("value").toString();var target=WorkTasks.record(db,"incident",child);candidate.put("revision",target.get("revision"));candidate.put("eligible",!child.equals(id) && Set.of("1","2").contains(object(target.get("data")).get("state")) && Set.of("","declined").contains(major(db,child).get("status")) && db.count("SELECT COUNT(*) FROM os_major_link WHERE child_id=? OR major_id=?",child,child)==0);}
  return map("incident",FieldAccess.serialize(db,incident),"major",major,"children",children,"has_parent",relation!=null,"parent",parent,"updates",updates(db,id),"search",search,"commander_name",db.one("SELECT COALESCE((SELECT name FROM os_user WHERE user_id=?),'Unassigned') AS name",major.get("commander_id")).get("name"),"staff","admin".equals(db.viewerRole)?db.all("SELECT name FROM os_user WHERE active=1 AND password_reset_required=0 AND role IN ('admin','agent') ORDER BY name LIMIT 200"):List.of(),"can_command","admin".equals(db.viewerRole) || db.viewerId.equals(major.get("commander_id")),"can_update",RecordPolicy.allows(Service.schema(db,"incident"),"update",db.viewerRole));
 }
 static Map<String,Object> command(Store.Db db,String id,Object input)throws SQLException{
  if(db.postgres)db.all("SELECT pg_advisory_xact_lock(18439,4)");var parent=WorkTasks.record(db,"incident",id);RecordPolicy.require(Service.schema(db,"incident"),"update",db.viewerRole);var major=major(db,id);var body=object(input);String operation=WorkJobs.text(body.get("operation"),8);var keys=new HashSet<>(Set.of("operation","revision","record_revision"));
  switch(operation){case "propose"->keys.addAll(Set.of("reason","impact"));case "accept"->keys.addAll(Set.of("commander","impact","reason"));case "assign"->keys.addAll(Set.of("commander","reason"));case "reject","reopen","close","demote"->keys.add("reason");case "publish"->keys.add("message");case "link","unlink"->keys.addAll(Set.of("child_id","child_revision"));case "restore"->keys.add("outcome");case "review"->keys.addAll(Set.of("cause","lessons","actions"));default->throw new Failure(400,"Choose a major-incident operation");}
  require(body.keySet().equals(keys),"Provide only the selected major-incident fields");ProblemInvestigations.revision(body.get("revision"),major.get("revision"));ProblemInvestigations.revision(body.get("record_revision"),parent.get("revision"));String status=major.get("status").toString(),state=object(parent.get("data")).get("state").toString();boolean admin="admin".equals(db.viewerRole);String target="";
  if(Set.of("accept","reject","assign","demote").contains(operation))Service.requireAccountAdministrator(db,db.viewerId);
  else if(!operation.equals("propose") && !admin && !db.viewerId.equals(major.get("commander_id")))throw new Failure(403,"Current incident commander required");
  if(body.containsKey("reason"))major.put("decision",WorkJobs.text(body.get("reason"),4000));
  switch(operation){
   case "propose"->{require(Set.of("","declined").contains(status) && Set.of("1","2").contains(state),"Propose an open incident without an active major process");require(db.count("SELECT COUNT(*) FROM os_major_link WHERE child_id=?",id)==0,"Detach this incident from its major parent before proposing it");major.putAll(map("status","candidate","proposal",WorkJobs.text(body.get("reason"),4000),"impact",WorkJobs.text(body.get("impact"),4000),"proposer_id",db.viewerId,"commander_id","","restoration","","review_cause","","review_lessons","","review_actions",""));}
   case "accept"->{require(status.equals("candidate") && Set.of("1","2").contains(state),"Accept only an open candidate");major.putAll(map("status","declared","commander_id",commander(db,body.get("commander"),id),"impact",WorkJobs.text(body.get("impact"),4000)));target="2";}
   case "reject"->{require(status.equals("candidate"),"Reject only a candidate");major.put("status","declined");}
   case "assign"->{require(Set.of("declared","restored","reviewed").contains(status),"Reassign an active major incident");major.put("commander_id",commander(db,body.get("commander"),id));if(status.equals("reviewed"))major.put("status","restored");}
   case "publish"->{require(Set.of("declared","restored","reviewed").contains(status),"Publish updates during an active major process");String message=WorkJobs.text(body.get("message"),4000);long ordinal=db.count("SELECT COUNT(*) FROM os_major_update WHERE parent_id=?",id)+1;require(ordinal<=100,"A major incident supports at most 100 published status updates");db.update("INSERT INTO os_major_update(update_id,parent_id,message,actor_id,ordinal,created) VALUES(?,?,?,?,?,?)",Values.id(),id,message,db.viewerId,ordinal,now());}
   case "link","unlink"->{require(Set.of("declared","restored","reviewed").contains(status) || operation.equals("unlink") && admin && status.equals("closed"),"Manage related incidents during the major process");String childId=WorkJobs.text(body.get("child_id"),32);var child=WorkTasks.record(db,"incident",childId);ProblemInvestigations.revision(body.get("child_revision"),child.get("revision"));RecordPolicy.require(Service.schema(db,"incident"),"update",db.viewerRole);
    if(operation.equals("link")){require(!id.equals(childId),"A major incident cannot contain itself");require(Set.of("1","2").contains(object(child.get("data")).get("state")),"Attach an open related incident");require(Set.of("","declined").contains(major(db,childId).get("status")),"An active major incident cannot be a child");require(db.count("SELECT COUNT(*) FROM os_major_link WHERE child_id=? OR major_id=?",childId,childId)==0,"Detach existing parent/children before attaching this incident");require(db.count("SELECT COUNT(*) FROM os_major_link WHERE major_id=?",id)<100,"A major incident supports at most 100 related incidents");db.update("INSERT INTO os_major_link(child_id,major_id) VALUES(?,?)",childId,id);}
    else if(db.update("DELETE FROM os_major_link WHERE child_id=? AND major_id=?",childId,id)!=1)throw new Failure(404,"Related incident link not found");if(status.equals("reviewed"))major.put("status","restored");
   }
   case "restore"->{require(status.equals("declared"),"Restore an active declared incident");major.putAll(map("status","restored","restoration",WorkJobs.text(body.get("outcome"),4000)));target="6";}
   case "review"->{require(Set.of("restored","reviewed").contains(status),"Review after service has been restored");major.putAll(map("status","reviewed","review_cause",WorkJobs.text(body.get("cause"),4000),"review_lessons",WorkJobs.text(body.get("lessons"),4000),"review_actions",WorkJobs.text(body.get("actions"),4000)));}
   case "reopen"->{require(Set.of("restored","reviewed").contains(status),"Reopen a restored incident before final closure");major.putAll(map("status","declared","review_cause","","review_lessons","","review_actions",""));target="2";}
   case "close"->{require(status.equals("reviewed"),"Complete the post-incident review before closure");major.put("status","closed");target="7";}
   default->{require(status.equals("declared"),"Demote only an active declared incident");require(db.count("SELECT COUNT(*) FROM os_major_link WHERE major_id=?",id)==0,"Detach related incidents before demoting");major.put("status","declined");}
  }
  db.update("INSERT INTO os_major_incident(incident_id,revision,status,commander_id,proposer_id,proposal,decision,impact,restoration,review_cause,review_lessons,review_actions,created,updated) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(incident_id) DO UPDATE SET revision=excluded.revision,status=excluded.status,commander_id=excluded.commander_id,proposer_id=excluded.proposer_id,proposal=excluded.proposal,decision=excluded.decision,impact=excluded.impact,restoration=excluded.restoration,review_cause=excluded.review_cause,review_lessons=excluded.review_lessons,review_actions=excluded.review_actions,updated=excluded.updated",id,((Number)major.get("revision")).intValue()+1,major.get("status"),major.get("commander_id"),major.get("proposer_id"),major.get("proposal"),major.get("decision"),major.get("impact"),major.get("restoration"),major.get("review_cause"),major.get("review_lessons"),major.get("review_actions"),major.get("created"),now());
  String actor=Service.account(db,db.viewerId).get("name").toString();Service.update(db,"incident",parent,target.isEmpty()?map():map("state",target),actor,db.viewerRole,body.get("record_revision").toString());Service.audit(db,parent,actor,"major."+operation,map("status",major.get("status")));return page(db,id,Map.of());
 }
 static void guard(Store.Db db,Map<String,Object> item)throws SQLException{
  if(!"incident".equals(item.get("table")))return;String id=item.get("sys_id").toString(),status=major(db,id).get("status").toString();if(!Set.of("6","7").contains(Objects.toString(object(item.get("data")).get("state"),"")) && db.count("SELECT COUNT(*) FROM os_major_link l JOIN os_major_incident m ON m.incident_id=l.major_id WHERE l.child_id=? AND m.status='closed'",id)>0)throw new Failure(409,"Detach this incident from its closed major parent before reopening");String expected=switch(status){case "declared"->"2";case "restored","reviewed"->"6";case "closed"->"7";default->"";};
  if(!expected.isEmpty() && !expected.equals(object(item.get("data")).get("state")))throw new Failure(409,"Use the major-incident workbench to restore, reopen or close this incident");
  if(status.equals("closed")){String state=db.postgres?"r.data->>'state'":"json_extract(r.data,'$.state')";if(db.count("SELECT COUNT(*) FROM os_major_link l JOIN os_record r ON r.sys_id=l.child_id WHERE l.major_id=? AND COALESCE("+state+",'') NOT IN ('6','7')",id)>0)throw new Failure(409,"Resolve all related incidents before closing the major incident");}
 }
 static void deleting(Store.Db db,String id)throws SQLException{
  if(db.count("SELECT COUNT(*) FROM os_major_link WHERE child_id=? OR major_id=?",id,id)>0)throw new Failure(409,"Detach major-incident relationships before deleting this incident");if(Set.of("candidate","declared","restored","reviewed").contains(major(db,id).get("status")))throw new Failure(409,"Reject, demote or close the major process before deleting this incident");
 }
 static Map<String,Object> queue(Store.Db db,Map<String,String> args)throws SQLException{
  if(!Set.of("admin","agent").contains(db.viewerRole))throw new Failure(403,"Staff access required");require(Set.of("status","limit","offset").containsAll(args.keySet()),"Use status, limit and offset");String status=args.getOrDefault("status","active");require(Set.of("active","candidate","closed","declined","all").contains(status),"Choose a supported major-incident status");int limit=Service.number(args.getOrDefault("limit","20"),1,100),offset=Service.number(args.getOrDefault("offset","0"),0,Integer.MAX_VALUE);var parameters=new ArrayList<Object>();var schema=Service.schema(db,"incident");String filter=RecordPolicy.allows(schema,"read",db.viewerRole) && FieldAccess.allowed(db,schema,"description") && FieldAccess.allowed(db,schema,"state")?RecordAccess.filter(db,"r.sys_id",parameters):"1=0";
  String sql=" FROM os_major_incident m JOIN os_record r ON r.sys_id=m.incident_id WHERE r.\"table\"='incident' AND "+filter;if(status.equals("active"))sql+=" AND m.status IN ('candidate','declared','restored','reviewed')";else if(!status.equals("all")){sql+=" AND m.status=?";parameters.add(status);}long total=db.count("SELECT COUNT(*)"+sql,parameters.toArray());parameters.add(limit);parameters.add(offset);var rows=db.all("SELECT r.*,m.status AS major_status"+sql+" ORDER BY m.updated DESC,r.seq DESC LIMIT ? OFFSET ?",parameters.toArray());var items=new ArrayList<Map<String,Object>>();for(var row:rows)items.add(map("incident",FieldAccess.serialize(db,row),"status",row.get("major_status")));return map("items",items,"status",status,"total",total,"limit",limit,"offset",offset,"next_offset",(long)offset+limit<total?(long)offset+limit:null);
 }
}
